#!/usr/bin/env python3
"""Validation script for pipeline outputs (Task T14)."""

import json
import os
import csv
from pathlib import Path


def validate_clean_stops(filepath: str) -> dict:
    """Validate cleaned GTFS stops file."""
    result = {
        "check_name": "clean_gtfs_stops",
        "passed": True,
        "message": ""
    }

    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            rows = list(reader)

        # Check required columns
        required_cols = ['stop_id', 'stop_name', 'stop_lat', 'stop_lon']
        for col in required_cols:
            if col not in reader.fieldnames:
                result["passed"] = False
                result["message"] = f"Missing required column: {col}"
                break

        # Check for valid coordinates
        for row in rows:
            try:
                lat = float(row['stop_lat'])
                lon = float(row['stop_lon'])
                if not (-90 <= lat <= 90) or not (-180 <= lon <= 180):
                    result["passed"] = False
                    result["message"] = f"Invalid coordinates: {row['stop_id']}"
                    break
            except (ValueError, KeyError):
                result["passed"] = False
                result["message"] = f"Invalid coordinates for stop: {row.get('stop_id', 'unknown')}"
                break

        result["message"] = f"Validated {len(rows)} stops successfully"
    except FileNotFoundError:
        result["passed"] = False
        result["message"] = f"File not found: {filepath}"
    except Exception as e:
        result["passed"] = False
        result["message"] = f"Error validating stops: {str(e)}"

    return result


def validate_clean_pois(filepath: str) -> dict:
    """Validate cleaned POIs file."""
    result = {
        "check_name": "clean_pois",
