        # Check required columns
        required_cols = ['qid', 'label', 'poi_type', 'latitude', 'longitude', 'source']
        for col in required_cols:
            if col not in reader.fieldnames:
                result["passed"] = False
                result["message"] = f"Missing required column: {col}"
                break

        # Check for valid coordinates
        for row in rows:
            try:
                lat = float(row['latitude'])
                lon = float(row['longitude'])
                if not (-90 <= lat <= 90) or not (-180 <= lon <= 180):
                    result["passed"] = False
                    result["message"] = f"Invalid coordinates: {row['qid']}"
                    break
            except (ValueError, KeyError):
                result["passed"] = False
                result["message"] = f"Invalid coordinates for POI: {row.get('qid', 'unknown')}"
                break

        result["message"] = f"Validated {len(rows)} POIs successfully"
    except FileNotFoundError:
        result["passed"] = False
        result["message"] = f"File not found: {filepath}"
    except Exception as e:
        result["passed"] = False
        result["message"] = f"Error validating POIs: {str(e)}"

    return result


def validate_accessibility_scores(filepath: str) -> dict:
    """Validate accessibility scores file."""
    result = {
        "check_name": "accessibility_scores",
        "passed": True,
        "message": ""
    }

    try:
        with open(filepath, 'r', encoding='utf-8') as f:
