            rows = list(reader)

        # Check required columns
        required_cols = ['city_id', 'city_name', 'year', 'cluster_id']
        for col in required_cols:
            if col not in reader.fieldnames:
                result["passed"] = False
                result["message"] = f"Missing required column: {col}"
                break

        # Check cluster_id values are numeric
        for row in rows:
            try:
                cluster_id = int(row['cluster_id'])
            except (ValueError, KeyError):
                result["passed"] = False
                result["message"] = f"Invalid cluster_id: {row.get('cluster_id', 'unknown')}"
                break

        result["message"] = f"Validated {len(rows)} city cluster records successfully"
    except FileNotFoundError:
        result["passed"] = False
        result["message"] = f"File not found: {filepath}"
    except Exception as e:
        result["passed"] = False
        result["message"] = f"Error validating city clusters: {str(e)}"

    return result


def validate_selected_indicators(filepath: str) -> dict:
    """Validate selected indicators file."""
    result = {
        "check_name": "selected_indicators",
        "passed": True,
        "message": ""
    }

    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            rows = list(reader)

        # Check required columns
        required_cols = ['indicator_id', 'indicator_name', 'theme', 'justification', 'expected_direction']
        for col in required_cols:
            if col not in reader.fieldnames:
                result["passed"] = False
                result["message"] = f"Missing required column: {col}"
                break

        result["message"] = f"Validated {len(rows)} indicators successfully"
    except FileNotFoundError:
        result["passed"] = False
        result["message"] = f"File not found: {filepath}"
    except Exception as e:
        result["passed"] = False
        result["message"] = f"Error validating indicators: {str(e)}"

    return result


def main():
    """Run all validations and generate summary."""
    base_dir = Path(__file__).parent.parent
    outputs_dir = base_dir / "outputs"
    src_dir = base_dir / "src"

    # Define validation checks with their file paths
    validations = [
        ("clean_gtfs_stops", str(outputs_dir / "t05_clean_stops.csv")),
        ("clean_pois", str(outputs_dir / "t08_pois_clean.csv")),
        ("accessibility_scores", str(outputs_dir / "t10_accessibility_scores.csv")),
        ("city_clusters", str(outputs_dir / "t13_city_clusters.csv")),
        ("selected_indicators", str(outputs_dir / "t01_selected_indicators.csv")),
    ]

    # Run validations
    results = []
    for check_name, filepath in validations:
        if check_name == "clean_gtfs_stops":
            result = validate_clean_stops(filepath)
        elif check_name == "clean_pois":
            result = validate_clean_pois(filepath)
        elif check_name == "accessibility_scores":
            result = validate_accessibility_scores(filepath)
        elif check_name == "city_clusters":
            result = validate_city_clusters(filepath)
        elif check_name == "selected_indicators":
            result = validate_selected_indicators(filepath)
        else:
            result = {"check_name": check_name, "passed": False, "message": "Unknown check"}
        results.append(result)

    # Write summary JSON
    summary_path = outputs_dir / "t14_validation_summary.json"
    with open(summary_path, 'w', encoding='utf-8') as f:
        json.dump(results, f, indent=2)

    print(f"Validation summary written to {summary_path}")
    print(f"Total checks: {len(results)}")
    print(f"Passed: {sum(1 for r in results if r['passed'])}")
    print(f"Failed: {sum(1 for r in results if not r['passed'])}")


if __name__ == "__main__":
    main()

